<?php require_once __DIR__.'/../config/auth.php';require_role('kasir');$s=db()->prepare("SELECT t.*,COALESCE(SUM(d.quantity),0) item_count FROM transactions t LEFT JOIN transaction_details d ON d.transaction_id=t.id WHERE t.cashier_id=? AND t.status='open' GROUP BY t.id ORDER BY t.created_at");$s->execute([user()['id']]);$orders=$s->fetchAll();$pageTitle='Pesanan Aktif';$active='pesanan';include __DIR__.'/../includes/header.php';?>
<?php if(isset($_GET['saved'])):?><div class="alert">Pesanan <?=e($_GET['saved'])?> berhasil disimpan. Stok sudah diperbarui.</div><?php endif;?><div class="active-orders"><?php foreach($orders as $o):?><article class="active-order-card"><div class="order-card-head"><div><span class="badge warn">Belum dibayar</span><h2><?=e($o['order_name']?:'Tanpa nama')?></h2><p><?=e($o['table_number']?'Meja '.$o['table_number']:'Bawa pulang')?> · <?=$o['item_count']?> item</p></div><strong><?=rupiah($o['total'])?></strong></div><div class="order-card-time"><i class="bi bi-clock"></i> Dibuka <?=date('H:i',strtotime($o['created_at']))?> · <?=max(0,(int)((time()-strtotime($o['created_at']))/60))?> menit lalu</div><div class="actions"><button class="btn primary pay-order" data-id="<?=$o['id']?>" data-total="<?=$o['total']?>" data-name="<?=e($o['order_name']?:'Pesanan')?>">Bayar</button><button class="btn danger cancel-order" data-id="<?=$o['id']?>">Batalkan</button></div></article><?php endforeach;?><?php if(!$orders):?><section class="card empty-state"><i class="bi bi-clipboard-check" style="font-size:42px"></i><h2>Tidak ada pesanan aktif</h2><p>Pesanan untuk bayar nanti akan muncul di sini.</p><a class="btn primary" href="kasir.php">Buat Pesanan</a></section><?php endif;?></div>
<div id="order-pay-modal" class="modal payment-modal"><div class="modal-card"><div class="card-head"><div><h2 id="order-pay-name">Bayar Pesanan</h2><small class="muted">Pastikan pelanggan dan meja sudah benar</small></div><button class="icon-btn order-modal-close"><i class="bi bi-x-lg"></i></button></div><div class="payment-total-card"><small>Total yang harus dibayar</small><strong id="order-pay-total">Rp0</strong></div><div class="payment-tabs"><button data-order-method="tunai" class="active"><i class="bi bi-cash-stack"></i><span><strong>Tunai</strong><small>Hitung uang kembali</small></span></button><button data-order-method="qris"><i class="bi bi-qr-code"></i><span><strong>QRIS</strong><small>Pakai QR yang ditempel</small></span></button></div><div id="order-cash"><label>Uang diterima<input id="order-amount" type="number" min="0" inputmode="numeric"></label><div class="change-card"><span>Kembalian</span><strong id="order-change">Rp0</strong></div></div><div id="order-qris" hidden><div class="qris-instruction"><i class="bi bi-qr-code-scan"></i><div><strong>Gunakan QRIS cetak</strong><p>Konfirmasi setelah pembayaran terlihat berhasil.</p></div></div></div><button id="finish-order" class="btn primary wide">Bayar Tunai &amp; Selesaikan</button><p id="order-error" class="payment-error"></p></div></div>
<script>let currentId=0,currentTotal=0,currentMethod='tunai';const modal=document.querySelector('#order-pay-modal'),fmt=n=>'Rp'+Number(n).toLocaleString('id-ID');document.querySelectorAll('.pay-order').forEach(b=>b.onclick=()=>{currentId=+b.dataset.id;currentTotal=+b.dataset.total;currentMethod='tunai';document.querySelector('#order-pay-name').textContent=b.dataset.name;document.querySelector('#order-pay-total').textContent=fmt(currentTotal);document.querySelector('#order-amount').value='';document.querySelector('#order-cash').hidden=false;document.querySelector('#order-qris').hidden=true;modal.classList.add('open')});document.querySelector('.order-modal-close').onclick=()=>modal.classList.remove('open');document.querySelectorAll('[data-order-method]').forEach(b=>b.onclick=()=>{document.querySelector('[data-order-method].active').classList.remove('active');b.classList.add('active');currentMethod=b.dataset.orderMethod;document.querySelector('#order-cash').hidden=currentMethod!=='tunai';document.querySelector('#order-qris').hidden=currentMethod==='tunai';document.querySelector('#finish-order').textContent=currentMethod==='tunai'?'Bayar Tunai & Selesaikan':'Konfirmasi QRIS Sudah Dibayar'});document.querySelector('#order-amount').oninput=e=>document.querySelector('#order-change').textContent=fmt(Math.max(0,+e.target.value-currentTotal));async function action(payload){const r=await fetch('<?=BASE_URL?>/api/order_action.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=csrf_token()?>'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.message);return d}document.querySelector('#finish-order').onclick=async()=>{const amount=currentMethod==='tunai'?+document.querySelector('#order-amount').value:currentTotal;if(amount<currentTotal){document.querySelector('#order-error').textContent='Uang diterima masih kurang.';return}try{await action({id:currentId,action:'pay',method:currentMethod,amount});location.href='riwayat.php'}catch(e){document.querySelector('#order-error').textContent=e.message}};document.querySelectorAll('.cancel-order').forEach(b=>b.onclick=async()=>{if(confirm('Batalkan pesanan ini? Stok akan dikembalikan.')){try{await action({id:+b.dataset.id,action:'cancel'});location.reload()}catch(e){alert(e.message)}}});</script><?php include __DIR__.'/../includes/footer.php';?>
